# shell: shaders
# all: no
# Every shader variant (src/render/shaders/quad.zig `variants`): the WGSL validated by naga and
# built into the quad pipeline on a real wgpu device (Mesa lavapipe); the committed translations in
# src/render/shaders/gen/ regenerated by naga-cli and required to match; the SPIR-V checked by
# spirv-val and the GLSL ES by glslangValidator.
src/render/shaders/translate.sh
python3 src/render/shaders/validate.py zig-out/shaders
stale() { echo "src/render/shaders/gen is stale: run src/render/shaders/translate.sh and commit" >&2; exit 1; }
git diff --exit-code --stat -- src/render/shaders/gen || stale
[ -z "$(git ls-files --others -- src/render/shaders/gen)" ] || stale
for f in src/render/shaders/gen/*.spv; do spirv-val "$f"; done
glslangValidator src/render/shaders/gen/*.vert src/render/shaders/gen/*.frag
echo "translations of $(ls src/render/shaders/gen/*.spv | wc -l) variants match and validate"
